#!/usr/bin/env python3
"""Boundary-free seed sweeps with 64-BIT seeds, on the GPU (CuPy + NVRTC; bgmt64.cu is generated by make_bgmt64.py from the validated bgmt.cu): the port of the
`prng-time` hypothesis (a program seeded from a MILLISECOND clock in 2012-2014: Java's 48-bit `new Random(System.currentTimeMillis())`, Python / Ruby two-word
MT19937 seeds above 2^32). Scoring, windows, variants, abort rule and the candidate floor are those of bg.py; only the seed width differs.

    python work/phpmt/bg64.py sweep  <py3|ruby|java|java-abs> <07|all> <lo> <hi> <out.tsv> [thr]      # seeds lo .. hi-1 (hi exclusive), any size below 2^63
    python work/phpmt/bg64.py verify <sweep.tsv> --gen <gen> [--top 10] [--range LO HI]          # whole-section check with INDEPENDENT keys (ref_keys64.py)
    python work/phpmt/bg64.py probe

Generators: py3 (CPython random.seed(int): randrange(29) | int(random() * 29)); ruby (the same seeding, rand(29) | float); java (new Random(long): nextInt(29) |
(int)(nextDouble() * 29)); java-abs (nextInt(29) | abs(nextInt()) % 29). A seed below 2^32 behaves as in bg.py (a Java int is sign-extended there). The TSV is
bg.py's: the `map` column is the kernel's map index (0 / 1) of the generator named on the command line.
"""
import argparse
import sys
import time
from pathlib import Path

import numpy as np

HERE = Path(__file__).resolve().parent
sys.path.insert(0, str(HERE))
sys.path.insert(0, str(HERE.parent))
import bg  # noqa: E402  (also sets the CuPy cache directory and imports gpu_common)
import ref_keys64  # noqa: E402

GENS64 = {"py3": (3, 0), "ruby": (9, 0), "java": (6, 0), "java-abs": (6, 1)}      # name -> (GEN of the kernel, JALT)
KERNEL64 = HERE / "bgmt64.cu"
K = bg.K


class Sweep64:
    def __init__(self, gen, wins, dump=0):
        import cupy as cp
        self.cp, self.gen, self.wins = cp, gen, wins
        g, jalt = GENS64[gen]
        defs = {"GEN": g, "NW": len(wins), "DUMP": dump, "JALT": jalt}
        src = "".join(f"#define {k} {v}\n" for k, v in defs.items()) + KERNEL64.read_text(encoding="utf-8")
        self.kernel = cp.RawModule(code=src, options=bg.NVRTC_OPTIONS).get_function("bg_kernel")
        runes = np.zeros((len(wins), bg.ROW), np.uint8)
        meta = np.zeros((len(wins), 4), np.int32)
        for k, (_, prev, r) in enumerate(wins):
            runes[k, :len(r)] = r
            meta[k] = (prev, len(r), bg.ABORT_AT, bg.ABORT_THR)
        self.d = [cp.asarray(runes.ravel()), cp.asarray(meta.ravel()), cp.asarray(bg.load_table().ravel())]
        self.hist = cp.zeros(bg.HB, cp.uint64)
        self.cand = cp.zeros(2 * bg.CCAP, cp.uint32)
        self.ccount = cp.zeros(1, cp.uint32)

    def launch(self, seed0, n, thr=bg.THR, dump=None):
        cp = self.cp
        self.ccount[:] = 0
        self.kernel(((n + bg.BLOCK - 1) // bg.BLOCK,), (bg.BLOCK,), (
            *self.d, np.uint64(seed0), np.uint64(n), np.int32(thr), self.hist, self.cand, self.ccount, np.uint32(bg.CCAP),
            dump if dump is not None else self.cand.view(cp.int32)))
        cp.cuda.Stream.null.synchronize()
        return int(self.ccount[0])

    def scores(self, lo, n):
        d = self.cp.zeros(n * len(self.wins) * 16, self.cp.int32)
        self.launch(lo, n, 1 << 30, d)
        return d.get().reshape(n, len(self.wins), 16)

    def keys(self, lo, n):
        """(n, 2, K) key values of the seeds lo .. lo + n - 1 (kernel built with dump=3)"""
        d = self.cp.zeros(n * 2 * K, self.cp.int32)
        self.launch(lo, n, 1 << 30, d)
        return d.get().reshape(n, 2, K)


def restore_seeds(base, low32):
    """the kernel records the low 32 bits of each seed; a chunk spans fewer than 2^32 seeds, so base + the offset of the low word from the base is the seed"""
    return base + ((low32.astype(np.int64) - (base & 0xFFFFFFFF)) & 0xFFFFFFFF)


def sweep(gen, spec, lo, hi, out, thr=bg.THR, wins=None, quiet=False):
    wins = wins if wins is not None else bg.make_windows(spec)
    S = Sweep64(gen, wins)
    if not quiet:
        info = bg.gpu_common.device_info()
        print(f"bg64: {gen} sweep of {hi - lo} seeds ({lo} .. {hi - 1}), {len(wins)} windows x 16 variants on CUDA {info['name']}", file=sys.stderr, flush=True)
    cand = np.zeros((0, 2), np.int64)
    hist = np.zeros(bg.HB, np.uint64)
    t_start = last = time.time()
    done, chunk, total = 0, 1 << 12, hi - lo
    while done < total:
        n = min(chunk, total - done)
        while True:
            S.hist[:] = 0
            t1 = time.time()
            cnt = S.launch(lo + done, n, thr)
            dt = time.time() - t1
            if cnt <= bg.CCAP:
                break
            thr += 25
        hist += S.hist.get()
        if cnt:
            raw = S.cand[:2 * cnt].get().reshape(cnt, 2)
            cand = np.concatenate([cand, np.column_stack([restore_seeds(lo + done, raw[:, 0]), raw[:, 1].astype(np.int64)])])
            if len(cand) > 4 * bg.TOPK:
                sc = cand[:, 1] >> 16
                cand = cand[sc >= int(np.sort(sc)[-bg.TOPK])]
        done += n
        chunk = int(min(max(chunk * min(2.0, bg.TARGET_S / max(dt, 1e-3)), 1 << 8), 1 << 24))
        if not quiet and time.time() - last >= 20:
            last = time.time()
            el, frac = last - t_start, done / total
            print(f"{100 * frac:.2f}% ({done} seeds) {done / el:.0f} seeds/s, eta {el * (1 - frac) / max(frac, 1e-9):.0f} s", file=sys.stderr, flush=True)
    secs = time.time() - t_start
    order = np.lexsort((cand[:, 1] & 0xFFFF, cand[:, 0], -(cand[:, 1] >> 16)))[:bg.TOPK]
    rows = ["score\tseed\twindow\tmodel\tmap\tsign\tatbash"]
    for seed, packed in cand[order]:
        s, wi, v = int(packed) >> 16, (int(packed) >> 8) & 0xFF, int(packed) & 0xFF
        model, mp, sign, atb = bg.variant_parts(v)
        rows.append(f"{s - 2048}\t{int(seed)}\t{wins[wi][0]}\t{model}\t{mp}\t{sign}\t{atb}")
    Path(out).write_text("\n".join(rows) + "\n", encoding="utf-8", newline="\n")
    best = (int(cand[order[0], 1] >> 16) - 2048) if len(order) else None
    if not quiet:
        print(f"swept {total} seeds in {secs:.0f} s; best score {best}; candidates >= {thr}: {len(cand)}", file=sys.stderr, flush=True)
        print("hist (bins of 20 from -400) " + " ".join(f"{b}:{int(c)}" for b, c in enumerate(hist) if c), file=sys.stderr, flush=True)
    return rows[1:], secs


# ------------------------------------------------------------------ whole-section check with independent keys

def verify(rows, gen, top=10, controls=8, rng_range=(1325376000000, 1391212800000), plant=None, out=print):
    """rows: TSV lines (score, seed, window, model, map, sign, atbash). Each row's window is decoded in full (the whole section, or `plant` = (prev, runes) for
    a window named 'plant') with keys from ref_keys64 (independent of the kernels) and compared with `controls` random seeds of the range through the same
    setting. CANDIDATE needs at least +2.0 per rune and 5 above every control. Returns the number of candidates."""
    import lp
    import stats
    tbl = bg.load_table()
    rng = np.random.default_rng(0)
    ncand = 0
    for line in rows[:top]:
        score, seed, window, model, mp, sign, atb = line.split("\t") if isinstance(line, str) else line
        seed, mp = int(seed), int(mp)
        if window == "plant":
            prev, c = plant
        else:
            sec = int(window.split(".")[1])
            c = np.array(lp.runes_of(stats.SEGS[sec]))
            prev = int(lp.runes_of(stats.SEGS[sec - 1])[-1]) if sec > 7 else -1
        cnt = 3 * len(c) + 60

        def whole(sd):
            s, _ = bg.ref_decode(c, prev, ref_keys64.keys(gen, int(sd), cnt)[mp], int(sign), bool(int(atb)), int(model), tbl)
            return s / len(c)

        real = whole(seed)
        rnd = [whole(x) for x in rng.integers(rng_range[0], rng_range[1], controls)]
        ok = real >= 2.0 and real >= max(rnd) + 5
        ncand += ok
        out(f"{'CANDIDATE' if ok else 'noise'}\t{score}\t{gen} seed {seed}\t{window} model {model} map {mp} sign {sign} atb {atb}: {real:+.2f} per rune over {len(c)} runes "
            f"(controls {np.mean(rnd):+.2f} +- {np.std(rnd):.2f}, max {max(rnd):+.2f})")
    return ncand


def main():
    a = sys.argv[1:]
    if a and a[0] == "probe":
        return bg.gpu_common.probe()
    if a and a[0] == "sweep" and len(a) >= 6:
        sweep(a[1], a[2], int(a[3]), int(a[4]), a[5], int(a[6]) if len(a) > 6 else bg.THR)
        return 0
    if a and a[0] == "verify":
        ap = argparse.ArgumentParser()
        ap.add_argument("tsv")
        ap.add_argument("--gen", required=True, choices=sorted(GENS64))
        ap.add_argument("--top", type=int, default=10)
        ap.add_argument("--range", nargs=2, type=int, default=[1325376000000, 1391212800000])
        p = ap.parse_args(a[1:])
        rows = [l for l in Path(p.tsv).read_text(encoding="utf-8").splitlines()[1:] if l.strip()]
        print(f"# boundary-free whole-section check of the best {min(p.top, len(rows))} candidates of {p.gen} (64-bit seeds): bigram score per rune over the WHOLE section "
              f"(a true key keeps about +10 per rune, a wrong one about -10.5), against 8 random seeds of {p.range[0]} .. {p.range[1]}; keys from ref_keys64.py (independent of the kernels)")
        if not rows:
            print("no candidate reached the sweep's floor")
            return 0
        verify(rows, p.gen, p.top, rng_range=tuple(p.range))
        return 0
    print(__doc__)
    return 2


if __name__ == "__main__":
    sys.exit(main())
